const item = $input.first().json;
const body = item.body || item;

// 1. Extraer y sanitizar datos de entrada
const rawMessage = typeof body.message === 'string' ? body.message : '';
const message = rawMessage.trim();
const conversationId = (body.conversationId || ('artlink-agent-' + Date.now())).toString().trim();
const rawHistory = Array.isArray(body.history) ? body.history : [];
const page = (body.page || '/').toString();
const role = (body.role || 'client').toString();

// 2. Validación de presencia y longitud
let validationError = null;
if (!message) {
  validationError = 'El mensaje no puede estar vacío. Por favor escribe tu consulta.';
} else if (message.length > 2000) {
  validationError = 'El mensaje excede el límite permitido de 2000 caracteres.';
}

// 3. Filtro de seguridad (contraseñas, tokens y tarjetas)
const sensitiveKeywordsRegex = /(password|contrase[ñn]a|token|bearer|api[_-]?key|secret|cvv|tarjeta\s*de\s*cr[ée]dito)/i;
const creditCardRegex = /\b(?:4[0-9]{12}(?:[0-9]{3})?|5[1-5][0-9]{14}|3[47][0-9]{13}|6(?:011|5[0-9]{2})[0-9]{12})\b/;

if (sensitiveKeywordsRegex.test(message) || creditCardRegex.test(message)) {
  validationError = 'Por seguridad de ArtLink, no ingreses contraseñas, tokens ni datos bancarios en el chat.';
}

// 4. Historial limitado a máximo 10 mensajes
const limitedHistory = rawHistory.slice(-10);

// 5. Prompt del clasificador de intención y selección de herramientas
const classifierPrompt = `Eres el clasificador de intenciones del Agente Oficial de ArtLink.
Tu labor es analizar la consulta del usuario y determinar si se requiere ejecutar alguna de las herramientas permitidas para consultar datos reales de la plataforma.

Herramientas disponibles:
1. "buscar_artistas": cuando el usuario busca artistas por disciplina (ej: Ilustración, 3D, Pixel Art, Anime), estilo, precio máximo o disponibilidad.
Parámetros: { "discipline": string|null, "style": string|null, "maxPrice": number|null, "availability": string|null, "query": string|null }

2. "consultar_perfil_artista": cuando el usuario pregunta por un artista específico, sus datos o portafolio.
Parámetros: { "artistNameOrId": string }

3. "consultar_estado_pedido": cuando el usuario pregunta por un encargo, pedido o comisión específica por su código.
Parámetros: { "orderId": string }

4. "consultar_tarifas": cuando el usuario pregunta por precios o paquetes de comisiones.
Parámetros: { "category": string|null, "maxPrice": number|null }

5. "solicitar_confirmacion": cuando el usuario pide explícitamente crear, encargar, modificar o enviar una comisión o dinero.
Parámetros: { "action": string, "artistName": string|null, "budget": number|null }

6. "ninguna": para saludos, preguntas generales sobre políticas de ArtLink, custodia Escrow o dudas que no requieren consultar la base de datos.

Contexto actual del usuario:
- Página actual: ${page}
- Rol: ${role}
- Consulta: "${message}"

Responde ÚNICAMENTE un objeto JSON válido con la siguiente estructura, sin texto adicional ni bloques markdown:
{
  "intent": "search_artists" | "get_artist_profile" | "check_order_status" | "check_rates" | "request_action" | "general_support",
  "tool": "buscar_artistas" | "consultar_perfil_artista" | "consultar_estado_pedido" | "consultar_tarifas" | "solicitar_confirmacion" | "ninguna",
  "toolParams": {},
  "directAnswer": "Respuesta breve si tool es ninguna, o null"
}`;

const isValid = !validationError;

return [{
  json: {
    isValid,
    validationError,
    conversationId,
    message,
    page,
    role,
    limitedHistory,
    classifierPayload: {
      contents: [
        {
          role: 'user',
          parts: [{ text: classifierPrompt }]
        }
      ],
      generationConfig: {
        temperature: 0.1,
        maxOutputTokens: 500,
        responseMimeType: 'application/json'
      }
    }
  }
}];

