const httpRes = $input.first().json;
const initialData = $('Validar Sesión y Contexto').item.json;
const resBody = httpRes.body || httpRes;

// 1. Extraer respuesta JSON del clasificador
let decision = {
  intent: 'general_support',
  tool: 'ninguna',
  toolParams: {},
  directAnswer: null
};

try {
  const candidates = resBody.candidates || [];
  if (candidates.length > 0 && candidates[0].content && candidates[0].content.parts) {
    const rawText = candidates[0].content.parts[0].text || '';
    const cleanJson = rawText.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
    decision = JSON.parse(cleanJson);
  }
} catch (err) {
  decision.directAnswer = null;
}

// 2. Ejecutar herramientas controladas contra la base de datos real de ArtLink
let toolResult = null;
let realData = [];
let toolError = null;
const tool = decision.tool || 'ninguna';
const params = decision.toolParams || {};

try {
  if (tool === 'buscar_artistas') {
    // Consultar perfiles reales de artistas en JSON Server
    const res = await fetch('http://localhost:3000/artistProfiles');
    const allArtists = await res.json();

    let filtered = Array.isArray(allArtists) ? allArtists : [];

    if (params.discipline) {
      const target = params.discipline.toLowerCase();
      filtered = filtered.filter(a => (a.disciplines || []).some(d => d.toLowerCase().includes(target)));
    }
    if (params.style) {
      const target = params.style.toLowerCase();
      filtered = filtered.filter(a => (a.styles || []).some(s => s.toLowerCase().includes(target)));
    }
    if (typeof params.maxPrice === 'number' && params.maxPrice > 0) {
      filtered = filtered.filter(a => Number(a.basePrice || 0) <= params.maxPrice);
    }
    if (params.availability) {
      filtered = filtered.filter(a => a.availability === params.availability);
    }
    if (params.query) {
      const q = params.query.toLowerCase();
      filtered = filtered.filter(a =>
        (a.displayName || '').toLowerCase().includes(q) ||
        (a.bio || '').toLowerCase().includes(q)
      );
    }

    realData = filtered.slice(0, 4).map(a => ({
      id: a.id,
      name: a.displayName,
      username: a.username,
      avatar: a.avatar,
      disciplines: a.disciplines,
      styles: a.styles,
      basePrice: a.basePrice,
      availability: a.availability,
      rating: a.rating
    }));

    toolResult = {
      toolExecuted: 'buscar_artistas',
      matchedCount: filtered.length,
      items: realData
    };
  } else if (tool === 'consultar_perfil_artista') {
    const term = (params.artistNameOrId || '').toLowerCase();
    const res = await fetch('http://localhost:3000/artistProfiles');
    const allArtists = await res.json();
    const found = (Array.isArray(allArtists) ? allArtists : []).find(a =>
      a.id.toLowerCase() === term ||
      (a.username || '').toLowerCase() === term ||
      (a.displayName || '').toLowerCase().includes(term)
    );

    if (found) {
      // Consultar comisiones del artista
      const commRes = await fetch(`http://localhost:3000/commissions?artistId=${found.id}`);
      const comms = await commRes.json();

      const artistInfo = {
        id: found.id,
        name: found.displayName,
        username: found.username,
        avatar: found.avatar,
        bio: found.bio,
        disciplines: found.disciplines,
        styles: found.styles,
        basePrice: found.basePrice,
        availability: found.availability,
        rating: found.rating,
        packages: (Array.isArray(comms) ? comms : []).slice(0, 3).map(c => ({
          id: c.id,
          title: c.title,
          price: c.price,
          deliveryDays: c.deliveryDays
        }))
      };
      realData = [artistInfo];
      toolResult = { toolExecuted: 'consultar_perfil_artista', found: true, artist: artistInfo };
    } else {
      toolResult = { toolExecuted: 'consultar_perfil_artista', found: false, searchAttempt: params.artistNameOrId };
    }
  } else if (tool === 'consultar_estado_pedido') {
    const orderId = (params.orderId || '').trim();
    const res = await fetch(`http://localhost:3000/requests?id=${orderId}`);
    const reqs = await res.json();
    const order = (Array.isArray(reqs) && reqs.length > 0) ? reqs[0] : null;

    if (order) {
      realData = [order];
      toolResult = { toolExecuted: 'consultar_estado_pedido', found: true, order };
    } else {
      toolResult = { toolExecuted: 'consultar_estado_pedido', found: false, orderId };
    }
  } else if (tool === 'consultar_tarifas') {
    const res = await fetch('http://localhost:3000/commissions');
    const comms = await res.json();
    let filtered = Array.isArray(comms) ? comms : [];
    if (params.category) {
      filtered = filtered.filter(c => (c.category || '').toLowerCase().includes(params.category.toLowerCase()));
    }
    if (typeof params.maxPrice === 'number') {
      filtered = filtered.filter(c => Number(c.price || 0) <= params.maxPrice);
    }
    realData = filtered.slice(0, 4);
    toolResult = { toolExecuted: 'consultar_tarifas', count: filtered.length, packages: realData };
  } else if (tool === 'solicitar_confirmacion') {
    toolResult = {
      toolExecuted: 'solicitar_confirmacion',
      requiresConfirmation: true,
      actionDetails: params
    };
  }
} catch (err) {
  toolError = err.message;
  toolResult = { toolExecuted: tool, error: 'No se pudo conectar con el servicio local de datos.' };
}

// 3. Preparar prompt para Gemini Step 2: Síntesis con datos reales y acciones UI
const synthesisPrompt = `Eres el Agente Inteligente de ArtLink.
Acabas de consultar la plataforma y tienes los siguientes resultados verificados:

- Consulta del usuario: "${initialData.message}"
- Herramienta ejecutada: ${tool}
- Resultado de la herramienta:
${JSON.stringify(toolResult, null, 2)}

Reglas ESTRICTAS:
1. Si la herramienta devolvió 0 resultados o found: false, NUNCA inventes artistas, precios ni datos falsos. Explica con amabilidad que no se encontraron coincidencias exactas y sugiere alternativas.
2. Si se encontraron artistas o datos, resume sus cualidades clave (nombre, tarifa base, disponibilidad) en español claro y breve.
3. Si la intención es crear o modificar información sensible (solicitar_confirmacion), pide explícitamente la confirmación del usuario.
4. Propón acciones útiles dentro de la interfaz (botones de navegación o filtros).

Responde ÚNICAMENTE un JSON válido con esta estructura exacta:
{
  "message": "Explicación clara en español para el usuario",
  "actions": [
    { "label": "Texto del botón", "type": "navigate", "url": "/ruta-artlink" }
  ],
  "confirmationRequired": null o { "action": "solicitar_comision", "details": {}, "prompt": "Pregunta de confirmación" }
}`;

return [{
  json: {
    ...initialData,
    decision,
    toolExecuted: tool,
    toolResult,
    realData,
    synthesisPayload: {
      contents: [
        {
          role: 'user',
          parts: [{ text: synthesisPrompt }]
        }
      ],
      generationConfig: {
        temperature: 0.3,
        maxOutputTokens: 800,
        responseMimeType: 'application/json'
      }
    }
  }
}];

const httpRes = $input.first().json;
const execData = $('Ejecutor de Herramientas ArtLink').item.json;
const conversationId = execData.conversationId;
const model = $env.GEMINI_MODEL || 'gemini-1.5-flash';

const statusCode = Number(httpRes.statusCode || (httpRes.error ? 500 : 200));
const resBody = httpRes.body || httpRes;

// 1. Manejo de errores de conexión o HTTP con Gemini
if (statusCode === 401 || statusCode === 403) {
  return [{
    json: {
      success: false,
      conversationId,
      message: 'Error de autenticación con Gemini. Verifica GEMINI_API_KEY en N8N.',
      provider: 'gemini',
      model,
      error: 'AUTH_ERROR'
    }
  }];
}

if (statusCode === 429) {
  return [{
    json: {
      success: false,
      conversationId,
      message: 'Límite de solicitudes de IA excedido temporalmente. Intenta de nuevo en unos momentos.',
      provider: 'gemini',
      model,
      error: 'RATE_LIMIT'
    }
  }];
}

// 2. Extraer síntesis estructurada del agente
let finalMessage = '';
let actions = [];
let confirmationRequired = null;

try {
  const candidates = resBody.candidates || [];
  if (candidates.length > 0 && candidates[0].content && candidates[0].content.parts) {
    const rawText = candidates[0].content.parts[0].text || '';
    const cleanJson = rawText.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(cleanJson);
    finalMessage = parsed.message || '';
    actions = Array.isArray(parsed.actions) ? parsed.actions : [];
    confirmationRequired = parsed.confirmationRequired || null;
  }
} catch (err) {
  finalMessage = execData.decision?.directAnswer || 'He procesado tu consulta sobre la plataforma ArtLink.';
}

// Si no hay mensaje generado por alguna razón, usar respuesta directa
if (!finalMessage) {
  finalMessage = execData.decision?.directAnswer || 'Consulta procesada con éxito.';
}

// 3. Respuesta final unificada del Agente
return [{
  json: {
    success: true,
    conversationId,
    message: finalMessage,
    provider: 'gemini',
    model,
    intent: execData.decision?.intent || 'general_support',
    toolUsed: execData.toolExecuted !== 'ninguna' ? execData.toolExecuted : null,
    data: execData.realData || [],
    actions,
    confirmationRequired
  }
}];
